-- Gymder: mock SQLite schema. Source of truth: gymder.dbml.
-- Conventions for this SQLite mock:
--   * ids are TEXT UUIDs (v4-shaped, generated by default)
--   * timestamps are TEXT, ISO 8601 UTC with milliseconds: YYYY-MM-DDTHH:MM:SS.sssZ
--     (keep this exact format so text comparison orders correctly)
--   * enums are TEXT with CHECK constraints; booleans are INTEGER 0/1
--   * foreign keys are only enforced when the connection runs: PRAGMA foreign_keys = ON;
--   * refresh_tokens is excluded (Supabase Auth owned it; it is legacy in the diagram)
--   * no row-level security in SQLite: authorization belongs to the backend

PRAGMA foreign_keys = ON;

CREATE TABLE profiles (
  id          TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6)))),
  full_name   VARCHAR(150) NOT NULL,
  role        TEXT NOT NULL DEFAULT 'student' CHECK (role IN ('student', 'coach')),
  avatar_path TEXT,
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE coaches (
  id                    TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6)))),
  profile_id            TEXT NOT NULL UNIQUE REFERENCES profiles (id) ON DELETE CASCADE,
  specialty             VARCHAR(150),
  bio                   TEXT,
  city                  VARCHAR(100),
  modality              TEXT CHECK (modality IS NULL OR modality IN ('online', 'in_person', 'hybrid')),
  starting_price        NUMERIC CHECK (starting_price >= 0),
  trial_class_available INTEGER NOT NULL DEFAULT 0 CHECK (trial_class_available IN (0, 1)),
  trial_class_price     NUMERIC CHECK (trial_class_price >= 0),
  currency_code         VARCHAR(3) CHECK (
                          currency_code IS NULL
                          OR (length(currency_code) = 3 AND currency_code NOT GLOB '*[^A-Z]*')),
  status                TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
  is_verified           INTEGER NOT NULL DEFAULT 0 CHECK (is_verified IN (0, 1)),
  verified_at           TEXT,
  verified_by           TEXT REFERENCES profiles (id),
  created_at            TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at            TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CONSTRAINT ck_coaches_price_currency
    CHECK ((starting_price IS NULL AND trial_class_price IS NULL) OR currency_code IS NOT NULL),
  CONSTRAINT ck_coaches_trial_price_availability
    CHECK (trial_class_price IS NULL OR trial_class_available = 1),
  CONSTRAINT ck_coaches_verification_audit
    CHECK ((is_verified = 1 AND verified_at IS NOT NULL AND verified_by IS NOT NULL)
        OR (is_verified = 0 AND verified_at IS NULL AND verified_by IS NULL))
);
CREATE INDEX idx_coaches_specialty   ON coaches (specialty);
CREATE INDEX idx_coaches_modality    ON coaches (modality);
CREATE INDEX idx_coaches_is_verified ON coaches (is_verified);
CREATE INDEX idx_coaches_status      ON coaches (status);
CREATE INDEX idx_coaches_verified_by ON coaches (verified_by);

CREATE TABLE plans (
  id            TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6)))),
  coach_id      TEXT NOT NULL REFERENCES coaches (id) ON DELETE CASCADE,
  tier          TEXT NOT NULL CHECK (tier IN ('start', 'plus', 'pro')),
  title         VARCHAR(150) NOT NULL CHECK (trim(title) <> ''),
  description   TEXT,
  price         NUMERIC NOT NULL CHECK (price >= 0),
  currency_code VARCHAR(3) NOT NULL CHECK (length(currency_code) = 3 AND currency_code NOT GLOB '*[^A-Z]*'),
  status        TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX idx_plans_coach_status ON plans (coach_id, status);
CREATE UNIQUE INDEX uq_plans_coach_tier ON plans (coach_id, tier);

CREATE TABLE coach_media (
  id         TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6)))),
  coach_id   TEXT NOT NULL REFERENCES coaches (id) ON DELETE CASCADE,
  image_url  TEXT NOT NULL,
  sort_order INTEGER NOT NULL DEFAULT 0 CHECK (sort_order >= 0),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX idx_coach_media_coach_sort ON coach_media (coach_id, sort_order);

CREATE TABLE favorites (
  profile_id TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  coach_id   TEXT NOT NULL REFERENCES coaches (id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (profile_id, coach_id)
);
CREATE INDEX idx_favorites_coach ON favorites (coach_id);

CREATE TABLE contact_requests (
  id          TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6)))),
  student_id  TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  coach_id    TEXT NOT NULL REFERENCES coaches (id) ON DELETE CASCADE,
  message     TEXT,
  status      TEXT NOT NULL DEFAULT 'pending'
              CHECK (status IN ('pending', 'accepted', 'declined', 'cancelled')),
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  resolved_at TEXT,
  -- resolved_at must be written together with the status change.
  CONSTRAINT ck_contact_requests_resolution
    CHECK ((status = 'pending' AND resolved_at IS NULL)
        OR (status <> 'pending' AND resolved_at IS NOT NULL AND resolved_at >= created_at))
);
CREATE INDEX idx_contact_requests_student_status ON contact_requests (student_id, status);
CREATE INDEX idx_contact_requests_coach_status   ON contact_requests (coach_id, status);
CREATE UNIQUE INDEX uq_contact_requests_pending_pair
  ON contact_requests (student_id, coach_id) WHERE status = 'pending';

CREATE TABLE conversations (
  id         TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6)))),
  student_id TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  coach_id   TEXT NOT NULL REFERENCES coaches (id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CONSTRAINT uq_conversations_pair UNIQUE (student_id, coach_id)
);
CREATE INDEX idx_conversations_coach ON conversations (coach_id);

CREATE TABLE messages (
  id              TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6)))),
  conversation_id TEXT NOT NULL REFERENCES conversations (id) ON DELETE CASCADE,
  sender_id       TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  body            TEXT NOT NULL CHECK (length(trim(body)) BETWEEN 1 AND 2000),
  created_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  read_at         TEXT,
  CONSTRAINT ck_messages_read_at CHECK (read_at IS NULL OR read_at >= created_at)
);
CREATE INDEX idx_messages_conversation_created ON messages (conversation_id, created_at);
CREATE INDEX idx_messages_sender ON messages (sender_id);

CREATE TABLE reviews (
  id         TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6)))),
  coach_id   TEXT NOT NULL REFERENCES coaches (id) ON DELETE CASCADE,
  student_id TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  rating     INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5),
  comment    TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CONSTRAINT uq_reviews_student_coach UNIQUE (student_id, coach_id)
);
CREATE INDEX idx_reviews_coach ON reviews (coach_id);

CREATE VIEW coach_stats AS
SELECT c.id AS coach_id,
       COALESCE(ROUND(AVG(r.rating), 1), 0) AS rating,
       COUNT(r.id) AS reviews_count
FROM coaches c
LEFT JOIN reviews r ON r.coach_id = c.id
GROUP BY c.id;

CREATE TABLE notifications (
  id                 TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6)))),
  recipient_id       TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  notification_type  TEXT NOT NULL CHECK (notification_type IN ('contact_request_created', 'contact_request_resolved', 'review_created')),
  contact_request_id TEXT REFERENCES contact_requests (id) ON DELETE CASCADE,
  review_id          TEXT REFERENCES reviews (id) ON DELETE CASCADE,
  created_at         TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at         TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  read_at            TEXT,
  CONSTRAINT ck_notifications_source
    CHECK ((notification_type IN ('contact_request_created', 'contact_request_resolved')
            AND contact_request_id IS NOT NULL AND review_id IS NULL)
        OR (notification_type = 'review_created' AND review_id IS NOT NULL AND contact_request_id IS NULL)),
  CONSTRAINT ck_notifications_read_at CHECK (read_at IS NULL OR read_at >= created_at)
);
CREATE INDEX idx_notifications_recipient_created ON notifications (recipient_id, created_at);
CREATE UNIQUE INDEX uq_notifications_recipient_type_request ON notifications (recipient_id, notification_type, contact_request_id);
CREATE UNIQUE INDEX uq_notifications_recipient_review ON notifications (recipient_id, review_id);
CREATE INDEX idx_notifications_contact_request ON notifications (contact_request_id);
CREATE INDEX idx_notifications_review ON notifications (review_id);

CREATE TABLE ads (
  id              TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6)))),
  advertiser_name VARCHAR(150) NOT NULL,
  title           VARCHAR(200) NOT NULL,
  image_url       TEXT,
  destination_url TEXT NOT NULL,
  status          TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
  starts_at       TEXT,
  ends_at         TEXT,
  created_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CONSTRAINT ck_ads_schedule CHECK (starts_at IS NULL OR ends_at IS NULL OR starts_at < ends_at)
);

-- Append-only: event content cannot be edited (see ad_events_immutable in the triggers migration).
-- Rows still go away through ON DELETE CASCADE (ad deleted); profile_id is nulled when a profile is deleted.
CREATE TABLE ad_events (
  id         TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6)))),
  ad_id      TEXT NOT NULL REFERENCES ads (id) ON DELETE CASCADE,
  profile_id TEXT REFERENCES profiles (id) ON DELETE SET NULL,
  event_type TEXT NOT NULL CHECK (event_type IN ('impression', 'click')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX idx_ad_events_ad_created ON ad_events (ad_id, created_at);
CREATE INDEX idx_ad_events_profile ON ad_events (profile_id);
